<?php
session_start();require_once __DIR__.'/config/database.php';$search=trim($_GET['search']??'');$cat=(int)($_GET['category']??0);$min=max(0,(float)($_GET['min']??0));$max=(float)($_GET['max']??0);$cats=[];$r=$conn->query("SELECT id,name FROM categories ORDER BY name");while($r&&$x=$r->fetch_assoc())$cats[]=$x;if($max<=0){$r=$conn->query("SELECT COALESCE(MAX(price),500)m FROM products");$max=(float)($r->fetch_assoc()['m']??500);}$max=max($min,$max);$sql="SELECT p.*,c.name category_name,b.name brand_name FROM products p LEFT JOIN categories c ON p.category_id=c.id LEFT JOIN brands b ON p.brand_id=b.id WHERE p.price BETWEEN ? AND ?";$types="dd";$params=[$min,$max];if($cat){$sql.=" AND p.category_id=?";$types.="i";$params[]=$cat;}if($search!==''){$sql.=" AND (p.name LIKE ? OR p.description LIKE ? OR c.name LIKE ? OR b.name LIKE ?)";$types.="ssss";$q="%$search%";array_push($params,$q,$q,$q,$q);}$sql.=" ORDER BY p.created_at DESC,p.id DESC";$s=$conn->prepare($sql);$s->bind_param($types,...$params);$s->execute();$products=$s->get_result();$cartCount=array_sum(array_map('intval',$_SESSION['cart']??[]));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products - SmartStore</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body><nav class="navbar main-navbar"><div class="container"><a class="navbar-brand text-white fw-bold" href="index.php">SmartStore</a><a href="cart.php" class="text-white text-decoration-none">Cart <span class="cart-nav-count"><?=$cartCount?></span></a></div></nav><main class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4 flex-wrap gap-3"><div><span class="page-eyebrow">SMARTSTORE COLLECTION</span><h1 class="fw-bold text-dark-custom">Explore Products</h1></div><a href="index.php" class="text-custom-primary">← Back to Home</a></div><form class="product-filter-card mb-4"><div class="row g-3 align-items-end"><div class="col-lg-4"><label class="form-label">Search</label><input name="search" value="<?=htmlspecialchars($search)?>" class="form-control" placeholder="Product, category or brand"></div><div class="col-lg-2"><label class="form-label">Category</label><select name="category" class="form-select"><option value="0">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat==(int)$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></div><div class="col-6 col-lg-2"><label class="form-label">Min $</label><input name="min" type="number" step=".01" value="<?=$min?>" class="form-control"></div><div class="col-6 col-lg-2"><label class="form-label">Max $</label><input name="max" type="number" step=".01" value="<?=$max?>" class="form-control"></div><div class="col-lg-2"><button class="btn custom-primary w-100 rounded-pill">Apply</button></div></div></form><div class="row g-4"><?php if($products->num_rows):while($p=$products->fetch_assoc()):?><div class="col-md-6 col-lg-4"><article class="collection-card h-100"><div class="collection-image"><span class="collection-badge <?=$p['stock']?'':'out-of-stock'?>"><?=$p['stock']?'In Stock':'Out of Stock'?></span><?php if($p['image']):?><img src="admin/assets/images/products/<?=htmlspecialchars($p['image'])?>" alt="<?=htmlspecialchars($p['name'])?>"><?php else:?><i class="bi bi-image fs-1"></i><?php endif;?></div><div class="collection-info"><small class="text-custom-primary fw-bold"><?=htmlspecialchars($p['category_name']??'Product')?><?=!empty($p['brand_name'])?' · '.htmlspecialchars($p['brand_name']):''?></small><h3><?=htmlspecialchars($p['name'])?></h3><p class="text-muted small"><?=htmlspecialchars($p['description']??'')?></p><div class="collection-price"><span>$<?=number_format((float)$p['price'],2)?></span></div><small class="text-muted">Stock: <?=intval($p['stock'])?></small></div><div class="product-actions"><a href="product-details.php?id=<?=$p['id']?>&action=order" class="product-btn product-btn-primary">Order Now</a><a href="product-details.php?id=<?=$p['id']?>" class="product-btn product-btn-secondary">View Details</a></div></article></div><?php endwhile;else:?><div class="col-12"><div class="empty-state"><h4>No products found</h4><p>Try another filter.</p></div></div><?php endif;?></div></main></body></html>